import * as THREE from 'three';
// IndexedDB holds dormant geometry outside the JavaScript heap. Restoring uses
// the original typed arrays and index data: no decimation or texture downgrade.
export function createResidency(world){
 // Terrain remains visible in mountain vistas even when far from the player.
 const meshes=world.builder.meshes.filter(m=>!m.isInstancedMesh);
 const records=meshes.map((mesh,id)=>{mesh.geometry.computeBoundingSphere();const sphere=mesh.geometry.boundingSphere.clone();return{mesh,id,sphere,bytes:Object.values(mesh.geometry.attributes).reduce((n,a)=>n+a.array.byteLength,mesh.geometry.index?.array.byteLength||0),cached:false,dormant:false,busy:false};});
 const stats={available:false,totalMiB:records.reduce((n,r)=>n+r.bytes,0)/1048576,residentMiB:0,dormantChunks:0,pending:0};stats.residentMiB=stats.totalMiB;let db=null,last=0,disabled=false,session=Date.now()+'-'+(crypto.randomUUID?.()||'scene');
 function operation(mode,fn){return new Promise((resolve,reject)=>{const tx=db.transaction('geometry',mode),store=tx.objectStore('geometry');let value;const req=fn(store);req.onsuccess=()=>value=req.result;tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
 const ready=new Promise(resolve=>{if(!globalThis.indexedDB)return resolve(false);const req=indexedDB.open('inari-geometry-v31',1);req.onupgradeneeded=()=>req.result.createObjectStore('geometry');req.onerror=()=>resolve(false);req.onsuccess=()=>{db=req.result;stats.available=true;resolve(true);const tx=db.transaction('geometry','readwrite'),cursor=tx.objectStore('geometry').openCursor();cursor.onsuccess=()=>{const c=cursor.result;if(!c)return;const timestamp=Number(String(c.key).split('-')[0]);if(timestamp&&Date.now()-timestamp>3600000)c.delete();c.continue();};};});
 async function cache(r){if(r.cached||r.busy||!db)return;r.busy=true;stats.pending++;try{const g=r.mesh.geometry,data={attrs:Object.fromEntries(Object.entries(g.attributes).map(([k,a])=>[k,{array:a.array,itemSize:a.itemSize,normalized:a.normalized}])),index:g.index?.array||null};await operation('readwrite',s=>s.put(data,session+':'+r.id));r.cached=true;}catch{disabled=true;}finally{r.busy=false;stats.pending--;}}
 function restore(r){
  if(!r.dormant||!db)return Promise.resolve();if(r.task)return r.task;
  r.busy=true;stats.pending++;
  r.task=(async()=>{try{const data=await operation('readonly',s=>s.get(session+':'+r.id));if(!data)throw Error('Missing cached geometry');const g=new THREE.BufferGeometry();for(const[k,a]of Object.entries(data.attrs))g.setAttribute(k,new THREE.BufferAttribute(a.array,a.itemSize,a.normalized));if(data.index)g.setIndex(new THREE.BufferAttribute(data.index,1));g.boundingSphere=r.sphere.clone();r.mesh.geometry.dispose();r.mesh.geometry=g;r.dormant=false;r.mesh.userData.residencyDormant=false;r.mesh.visible=true;stats.residentMiB+=r.bytes/1048576;stats.dormantChunks--;}catch(e){stats.error=e.message;disabled=true;}finally{r.busy=false;r.task=null;stats.pending--;}})();return r.task;
 }
 function evict(r){if(!r.cached||r.busy||r.dormant)return;const old=r.mesh.geometry,empty=new THREE.BufferGeometry();empty.setAttribute('position',new THREE.BufferAttribute(new Float32Array(0),3));empty.boundingSphere=r.sphere.clone();r.mesh.geometry=empty;r.mesh.visible=false;r.mesh.userData.residencyDormant=true;old.dispose();r.dormant=true;stats.residentMiB-=r.bytes/1048576;stats.dormantChunks++;}
 return{stats,ready,records,prefetch(point,radius=350){return ready.then(()=>Promise.all(records.filter(r=>r.dormant&&point.distanceTo(r.sphere.center)-r.sphere.radius<radius).map(restore)));},async settle(){await ready;await Promise.all(records.filter(r=>r.busy).map(()=>new Promise(r=>setTimeout(r,50))))},update(camera,mode,wide=false){if(!db)return;const now=performance.now();if(now-last>400){last=now;let writes=0,reads=0;const ordered=records.slice().sort((a,b)=>camera.position.distanceToSquared(a.sphere.center)-camera.position.distanceToSquared(b.sphere.center));for(const r of ordered){const d=camera.position.distanceTo(r.sphere.center)-r.sphere.radius,load=wide?Infinity:mode==='overview'?760:325,unload=wide?Infinity:mode==='overview'?900:430;
 if(r.dormant&&d<load&&(reads<48||d<210)){restore(r);reads++;}else if(!disabled&&!r.dormant&&d>unload){if(r.cached)evict(r);else if(writes<10){cache(r);writes++;}}
 }}for(const r of records)if(r.dormant)r.mesh.visible=false;}};
}
